B.ae4=s(["\u0623\u0646\u062a \u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0635\u062d\u0629 \u0645\u0627 \u062a\u0646\u0634\u0631\u0647 \u0645\u0646 \u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0648\u0635\u0648\u0631 \u0648\u0623\u0633\u0639\u0627\u0631 \u0648\u0648\u0635\u0641 \u0648\u0631\u0633\u0627\u0626\u0644\u060c \u0648\u0639\u0646 \u0627\u0645\u062a\u0644\u0627\u0643\u0643 \u062d\u0642 \u0646\u0634\u0631\u0647.","\u064a\u064f\u0645\u0646\u0639 \u0646\u0634\u0631: \u0627\u0644\u0633\u0644\u0639 \u0623\u0648 \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0629 \u0644\u0644\u0642\u0627\u0646\u0648\u0646\u060c \u0648\u0627\u0644\u0623\u062f\u0648\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u062d\u062a\u0627\u062c \u0631\u0648\u0634\u062a\u0629\u060c \u0648\u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u0633\u064a\u0621 \u0623\u0648 \u0627\u0644\u0645\u0636\u0644\u0644 \u0623\u0648 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0644\u064a\u060c \u0648\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0622\u062e\u0631\u064a\u0646 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0628\u062f\u0648\u0646 \u0625\u0630\u0646\u0647\u0645\u060c \u0648\u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0632\u0639\u062c\u0629 \u0627\u0644\u0645\u0643\u0631\u0631\u0629.","\u062a\u0645\u0646\u062d\u0646\u0627 \u0625\u0630\u0646\u0627\u064b \u0628\u0639\u0631\u0636 \u0645\u0627 \u062a\u0646\u0634\u0631\u0647 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0646\u0635\u0629 \u0648\u0645\u0634\u0627\u0631\u0643\u0629 \u0631\u0648\u0627\u0628\u0637\u0647\u060c \u0648\u064a\u062d\u0642 \u0644\u0646\u0627 \u062d\u0630\u0641 \u0623\u064a \u0645\u062d\u062a\u0648\u0649 \u0645\u062e\u0627\u0644\u0641."],t.s)
B.a1r=new A.eP("\u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0630\u064a \u062a\u0646\u0634\u0631\u0647",B.ae4)
B.a6K=s(["\u0627\u0644\u062a\u0627\u062c\u0631 \u0648\u062d\u062f\u0647 \u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0645\u0646\u062a\u062c\u0627\u062a\u0647 \u0648\u0623\u0633\u0639\u0627\u0631\u0647\u0627 \u0648\u062c\u0648\u062f\u062a\u0647\u0627 \u0648\u062a\u0648\u0641\u0631\u0647\u0627 \u0648\u0645\u0635\u0627\u0631\u064a\u0641 \u0627\u0644\u062a\u0648\u0635\u064a\u0644 \u0627\u0644\u062a\u064a \u064a\u062d\u062f\u062f\u0647\u0627\u060c \u0648\u0639\u0646 \u062a\u062c\u0647\u064a\u0632 \u0627\u0644\u0637\u0644\u0628 \u0648\u062a\u0633\u0644\u064a\u0645\u0647 \u0648\u0623\u064a \u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0623\u0648 \u0627\u0633\u062a\u0631\u062c\u0627\u0639.","\u0627\u0644\u062f\u0641\u0639 \u062d\u0627\u0644\u064a\u0627\u064b \u0639\u0646\u062f \u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645 \u0645\u0628\u0627\u0634\u0631\u0629 \u0628\u064a\u0646 \u0627\u0644\u0639\u0645\u064a\u0644 \u0648\u0627\u0644\u062a\u0627\u062c\u0631\u060c \u0648\u0627\u0644\u0645\u0646\u0635\u0629 \u0644\u0627 \u062a\u0633\u062a\u0644\u0645 \u0648\u0644\u0627 \u062a\u062d\u062a\u0641\u0638 \u0628\u0623\u064a \u0645\u0628\u0627\u0644\u063a \u0645\u0642\u0627\u0628\u0644 \u0627\u0644\u0637\u0644\u0628\u0627\u062a.","\u0627\u0644\u0635\u0648\u0631 \u0648\u0627\u0644\u0623\u0648\u0635\u0627\u0641 \u0627\u0644\u062c\u0627\u0647\u0632\u0629 \u0648\u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0647\u064a \u0645\u0633\u0627\u0639\u062f\u0629 \u0644\u0644\u062a\u0627\u062c\u0631\u060c \u0648\u0639\u0644\u064a\u0647 \u0645\u0631\u0627\u062c\u0639\u062a\u0647\u0627 \u0648\u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0645\u0637\u0627\u0628\u0642\u062a\u0647\u0627 \u0644\u0645\u0627 \u064a\u0628\u064a\u0639\u0647 \u0641\u0639\u0644\u0627\u064b.","\u064a\u062c\u0628 \u0639\u0644\u0649 \u0627\u0644\u062a\u0627\u062c\u0631 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u0627\u0621 (\u0627\u0644\u0627\u0633\u0645 \u0648\u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644 \u0648\u0627\u0644\u0639\u0646\u0648\u0627\u0646) \u0644\u062a\u0648\u0635\u064a\u0644 \u0627\u0644\u0637\u0644\u0628 \u0641\u0642\u0637\u060c \u0648\u0639\u062f\u0645 \u0645\u0634\u0627\u0631\u0643\u062a\u0647\u0627 \u0623\u0648 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0627 \u0641\u064a \u0623\u064a \u063a\u0631\u0636 \u0622\u062e\u0631."],t.s)
B.a1p=new A.eP("\u0627\u0644\u0645\u062a\u0627\u062c\u0631 \u0648\u0627\u0644\u0637\u0644\u0628\u0627\u062a",B.a6K)
B.aeE=s(["\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0648\u0633\u064a\u0644\u0629 \u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0639\u0646\u0648\u0627\u0646\u0643 \u0628\u0633\u0647\u0648\u0644\u0629. \u0623\u0646\u062a \u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0635\u062d\u062a\u0647 \u0648\u0639\u0645\u0651\u0646 \u062a\u0634\u0627\u0631\u0643\u0647 \u0645\u0639\u0647\u060c \u0648\u064a\u0645\u0643\u0646\u0643 \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0643\u0648\u062f \u0623\u0648 \u062d\u0630\u0641 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0641\u064a \u0623\u064a \u0648\u0642\u062a.","\u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0645\u0645\u064a\u0632\u0629 \u0627\u0644\u0645\u0643\u0648\u0646\u0629 \u0645\u0646 \u0643\u0644\u0645\u0629 \u0648\u0627\u062d\u062f\u0629 \u0645\u062d\u062c\u0648\u0632\u0629 \u0644\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0646\u0635\u0629 \u0648\u064a\u0645\u0643\u0646 \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u064a\u0647\u0627 \u0628\u0637\u0644\u0628."],t.s)
B.a1i=new A.eP("\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a",B.aeE)
B.a1V=s(["\u0627\u0644\u0645\u0646\u0635\u0629 \u0623\u062f\u0627\u0629 \u0644\u062a\u0646\u0638\u064a\u0645 \u0634\u0624\u0648\u0646 \u0627\u0644\u0639\u0645\u0627\u0631\u0629 (\u0627\u0644\u0623\u0639\u0636\u0627\u0621 \u0648\u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643\u0627\u062a \u0648\u0627\u0644\u0642\u0631\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u062a\u0635\u0648\u064a\u062a \u0648\u0627\u0644\u0635\u064a\u0627\u0646\u0629)\u060c \u0648\u0644\u0627 \u062a\u063a\u0646\u064a \u0639\u0646 \u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0644\u0627\u062a\u062d\u0627\u062f \u0627\u0644\u0634\u0627\u063a\u0644\u064a\u0646.","\u0631\u0626\u0627\u0633\u0629 \u0627\u0644\u0627\u062a\u062d\u0627\u062f \u062a\u0643\u0648\u0646 \u0628\u0645\u0648\u0627\u0641\u0642\u0629 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0646\u0635\u0629 \u0628\u0639\u062f \u0627\u0644\u062a\u062d\u0642\u0642\u060c \u0623\u0648 \u0628\u0627\u0646\u062a\u062e\u0627\u0628 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0643 \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642. \u0648\u064a\u0644\u062a\u0632\u0645 \u0643\u0644 \u0639\u0636\u0648 \u0628\u062a\u0642\u062f\u064a\u0645 \u0628\u064a\u0627\u0646\u0627\u062a \u0635\u062d\u064a\u062d\u0629 \u0639\u0646 \u0648\u062d\u062f\u062a\u0647 \u0648\u0635\u0641\u062a\u0647.","\u0625\u062f\u0627\u0631\u0629 \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0627\u062a\u062d\u0627\u062f \u0648\u062a\u062d\u0635\u064a\u0644\u0647\u0627 \u0648\u0635\u0631\u0641\u0647\u0627 \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0627\u0644\u0627\u062a\u062d\u0627\u062f \u0648\u0623\u0639\u0636\u0627\u0626\u0647\u060c \u0648\u0627\u0644\u0645\u0646\u0635\u0629 \u0644\u0627 \u062a\u062d\u062a\u0641\u0638 \u0628\u0647\u0627."],t.s)
B.a1j=new A.eP("\u0627\u062a\u062d\u0627\u062f \u0627\u0644\u0645\u0644\u0627\u0643",B.a1V)
B.a5q=s(["\u0634\u062d\u0646 \u0627\u0644\u0631\u0635\u064a\u062f \u064a\u062a\u0645 \u0628\u062a\u062d\u0648\u064a\u0644 \u064a\u062f\u0648\u064a \u0648\u062a\u0623\u0643\u064a\u062f\u0647 \u0645\u0646 \u0627\u0644\u0625\u062f\u0627\u0631\u0629\u060c \u0648\u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0646\u0635\u0629 \u0641\u0642\u0637 \u0641\u064a \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0645\u0639\u0631\u0648\u0636\u0629 \u0628\u0623\u0633\u0639\u0627\u0631\u0647\u0627 \u0627\u0644\u0638\u0627\u0647\u0631\u0629. \u0623\u064a \u0637\u0644\u0628 \u0633\u062d\u0628 \u0623\u0648 \u0627\u0633\u062a\u0631\u062f\u0627\u062f \u064a\u064f\u0631\u0627\u062c\u0639 \u064a\u062f\u0648\u064a\u0627\u064b."],t.s)
